data\";s:36:\"瀬戸内ことり (Setouchi Kotori)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:141:\"https://ja.wordpress.org/support/topic/%e3%82%ab%e3%82%b9%e3%82%bf%e3%83%a0html%e3%81%a7%e3%81%ae%e4%b8%8d%e5%85%b7%e5%90%88-2/#post-11691838\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"カスタムHTMLでの不具合\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:141:\"https://ja.wordpress.org/support/topic/%e3%82%ab%e3%82%b9%e3%82%bf%e3%83%a0html%e3%81%a7%e3%81%ae%e4%b8%8d%e5%85%b7%e5%90%88-2/#post-11691838\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 01 May 2025 14:46:42 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3586:\"\n						\n						<p>このページにおいてカスタムHTMLを導入して、クリッカブルマップを導入しようとしたのですがどうしてもその指定した範囲がずれて本来四つある範囲も一つしか反映されません</p>\n\n\n\n<p>コードがだめなのかと思い、他サイトでhtmlを実行したのですがそちらでは正常に作動しました。<br />以下そのコードです</p>\n\n\n\n<p>完璧にコピペすると画像に変換されるので一番最初はコードが欠けています</p>\n\n\n\n<p> &lt;mg src=&#8221;<a href=\"http://0moide.com/wp-content/uploads/2025/05/見取り図-2.png&#038;#8221\" rel=\"nofollow ugc\">http://0moide.com/wp-content/uploads/2025/05/見取り図-2.png&#038;#8221</a>; usemap=&#8221;#ImageMap&#8221; alt=&#8221;&#8221; /&gt;<br />&lt;map name=&#8221;ImageMap&#8221;&gt;<br />  &lt;area shape=&#8221;rect&#8221; coords=&#8221;208,278,565,419&#8243; href=&#8221;<a href=\"https://0moide.com/2025/05/01/%e6%97%a5%e7%94%a8%e5%93%81/&#038;#8221\" rel=\"nofollow ugc\">https://0moide.com/2025/05/01/%e6%97%a5%e7%94%a8%e5%93%81/&#038;#8221</a>; alt=&#8221;&#8221; /&gt;<br />  &lt;area shape=&#8221;rect&#8221; coords=&#8221;909,474,1282,626&#8243; href=&#8221;<a href=\"https://0moide.com/2025/05/01/%e3%81%8a%e3%81%84%e3%81%97%e3%81%84%e3%81%8a%e5%ba%97/&#038;#8221\" rel=\"nofollow ugc\">https://0moide.com/2025/05/01/%e3%81%8a%e3%81%84%e3%81%97%e3%81%84%e3%81%8a%e5%ba%97/&#038;#8221</a>; alt=&#8221;&#8221; /&gt;<br />  &lt;area shape=&#8221;rect&#8221; coords=&#8221;585,734,1193,917&#8243; href=&#8221;<a href=\"https://0moide.com/2025/05/01/%e3%82%a8%e3%83%b3%e3%83%88%e3%83%a9%e3%83%b3%e3%82%b9/&#038;#8221\" rel=\"nofollow ugc\">https://0moide.com/2025/05/01/%e3%82%a8%e3%83%b3%e3%83%88%e3%83%a9%e3%83%b3%e3%82%b9/&#038;#8221</a>; alt=&#8221;&#8221; /&gt;<br />  &lt;area shape=&#8221;rect&#8221; coords=&#8221;1257,316,1464,396&#8243; href=&#8221;<a href=\"https://0moide.com/2025/05/01/%e9%8a%ad%e6%b9%af%e3%82%a8%e3%83%aa%e3%82%a2/&#038;#8221\" rel=\"nofollow ugc\">https://0moide.com/2025/05/01/%e9%8a%ad%e6%b9%af%e3%82%a8%e3%83%aa%e3%82%a2/&#038;#8221</a>; alt=&#8221;&#8221; /&gt;<br />&lt;/map&gt;</p>\n\n\n\n<figure class=\"wp-block-image\"><img src=\"http://0moide.com/wp-content/uploads/2025/05/見取り図-2.png\" alt=\"\" /></figure>\n\n\n\n<p><br /></p>\n\n\n\n<figure class=\"wp-block-image is-resized\"><img src=\"http://0moide.com/wp-content/uploads/2025/05/見取り図-2.png\" alt=\"\" /></figure>\n\n\n\n<p>ずっとここで引っかかって前に進めません。<br />運営初めて間もないのでどうかご教授いただけるととても助かります。</p>\n\n\n<ul id=\"bbp-topic-revision-log-11691838\" class=\"bbp-topic-revision-log\">\n\n	<li id=\"bbp-topic-revision-log-11691838-item-11691839\" class=\"bbp-topic-revision-log-item\">\n		このトピックは<a href=\"https://ja.wordpress.org/support/users/setouchikotori/\" title=\"瀬戸内ことり (Setouchi Kotori) のプロフィールを表示\" class=\"bbp-author-link\"><span  class=\"bbp-author-name\">瀬戸内ことり (Setouchi Kotori)</span></a>が2日、 22時間前に変更しました。\n	</li>\n	<li id=\"bbp-topic-revision-log-11691838-item-11691841\" class=\"bbp-topic-revision-log-item\">\n		このトピックは2日、 22時間前に<a href=\"https://ja.wordpress.org/support/users/kagura0812/\" title=\"kagura0812 のプロフィールを表示\" class=\"bbp-author-link\"><span  class=\"bbp-author-name\">kagura0812</span></a>が編集しました。理由: コードが共有されていなかったようです。すみません\n	</li>\n\n</ul>\n\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"kagura0812\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:173:\"https://ja.wordpress.org/support/topic/%e3%83%87%e3%83%bc%e3%82%bf%e3%83%99%e3%83%bc%e3%82%b9%e6%8e%a5%e7%b6%9a%e7%a2%ba%e7%ab%8b%e3%82%a8%e3%83%a9%e3%83%bc-8/#post-11691837\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:50:\"返信先: データベース接続確立エラー\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:173:\"https://ja.wordpress.org/support/topic/%e3%83%87%e3%83%bc%e3%82%bf%e3%83%99%e3%83%bc%e3%82%b9%e6%8e%a5%e7%b6%9a%e7%a2%ba%e7%ab%8b%e3%82%a8%e3%83%a9%e3%83%bc-8/#post-11691837\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 01 May 2025 07:00:31 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"\n						\n						<p>解決しました。ありがとうございました。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"jkjm\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:173:\"https://ja.wordpress.org/support/topic/%e3%83%87%e3%83%bc%e3%82%bf%e3%83%99%e3%83%bc%e3%82%b9%e6%8e%a5%e7%b6%9a%e7%a2%ba%e7%ab%8b%e3%82%a8%e3%83%a9%e3%83%bc-8/#post-11691836\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:50:\"返信先: データベース接続確立エラー\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:173:\"https://ja.wordpress.org/support/topic/%e3%83%87%e3%83%bc%e3%82%bf%e3%83%99%e3%83%bc%e3%82%b9%e6%8e%a5%e7%b6%9a%e7%a2%ba%e7%ab%8b%e3%82%a8%e3%83%a9%e3%83%bc-8/#post-11691836\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 01 May 2025 06:28:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2685:\"\n						\n						<p>返信ありがとうございます。<br />SLL証明書は有効期限内でした。パスが間違っていたのかと思い再度書き換えを行ったのですが、その後は以下の表記が現れるようになりました。</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p><strong>Notice</strong>: Function _load_textdomain_just_in_time was called&nbsp;<strong>incorrectly</strong>. Translation loading for the&nbsp;<code>backwpup</code>&nbsp;domain was triggered too early. This is usually an indicator for some code in the plugin or theme running too early. Translations should be loaded at the&nbsp;<code>init</code>&nbsp;action or later. Please see&nbsp;<a href=\"https://developer.wordpress.org/advanced-administration/debug/debug-wordpress/\" rel=\"nofollow ugc\">Debugging in WordPress</a>&nbsp;for more information. (This message was added in version 6.7.0.) in&nbsp;<strong>/home/morinohiroba/public_html/morinohiroba.com/wp-includes/functions.php</strong>&nbsp;on line&nbsp;<strong>6121</strong></p>\n\n\n\n<p><strong>Fatal error</strong>: Uncaught Error: Call to undefined function cal_days_in_month() in /home/morinohiroba/public_html/morinohiroba.com/wp-content/plugins/backwpup/inc/class-cron.php:372 Stack trace: #0 /home/morinohiroba/public_html/morinohiroba.com/wp-content/plugins/backwpup/inc/class-install.php(93): BackWPup_Cron::cron_next(&#8216;0 0 1 * *&#8217;) #1 /home/morinohiroba/public_html/morinohiroba.com/wp-content/plugins/backwpup/backwpup.php(74): BackWPup_Install::activate() #2 /home/morinohiroba/public_html/morinohiroba.com/wp-content/plugins/backwpup/backwpup.php(196): BackWPup-&gt;__construct() #3 /home/morinohiroba/public_html/morinohiroba.com/wp-includes/class-wp-hook.php(324): BackWPup::get_instance(&#8221;) #4 /home/morinohiroba/public_html/morinohiroba.com/wp-includes/class-wp-hook.php(348): WP_Hook-&gt;apply_filters(NULL, Array) #5 /home/morinohiroba/public_html/morinohiroba.com/wp-includes/plugin.php(517): WP_Hook-&gt;do_action(Array) #6 /home/morinohiroba/public_html/morinohiroba.com/wp-settings.php(578): do_action(&#8216;plugins_loaded&#8217;) #7 /home/m in&nbsp;<strong>/home/morinohiroba/public_html/morinohiroba.com/wp-content/plugins/backwpup/inc/class-cron.php</strong>&nbsp;on line&nbsp;<strong>372</strong></p>\n\n\n\n<p>この Web サイトに重大なエラーが発生しました。サイト管理者のメール受信箱で手順を確認してください。問題が解決しない場合は、<a href=\"https://ja.wordpress.org/support/forums/\" rel=\"ugc\">サポートフォーラム</a>&nbsp;をお試しください。</p>\n</blockquote>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"jkjm\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:248:\"https://ja.wordpress.org/support/topic/%e3%81%93%e3%81%ae-web-%e3%82%b5%e3%82%a4%e3%83%88%e3%81%ab%e9%87%8d%e5%a4%a7%e3%81%aa%e3%82%a8%e3%83%a9%e3%83%bc%e3%81%8c%e7%99%ba%e7%94%9f%e3%81%97%e3%81%be%e3%81%97%e3%81%9f%e3%80%82%e3%81%a8/#post-11691834\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"返信先: この Web サイトに重大なエラーが発生しました。と表示され\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:248:\"https://ja.wordpress.org/support/topic/%e3%81%93%e3%81%ae-web-%e3%82%b5%e3%82%a4%e3%83%88%e3%81%ab%e9%87%8d%e5%a4%a7%e3%81%aa%e3%82%a8%e3%83%a9%e3%83%bc%e3%81%8c%e7%99%ba%e7%94%9f%e3%81%97%e3%81%be%e3%81%97%e3%81%9f%e3%80%82%e3%81%a8/#post-11691834\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 01 May 2025 04:22:46 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1562:\"\n						\n						<p>『<a href=\"https://ja.wordpress.org/support/topic/%e5%95%8f%e9%a1%8c%e8%a7%a3%e6%b1%ba%e3%81%ae%e3%81%9f%e3%82%81%e3%81%ae%e3%83%81%e3%82%a7%e3%83%83%e3%82%af%e3%83%aa%e3%82%b9%e3%83%88-%e3%83%89%e3%83%a9%e3%83%95%e3%83%88%e7%89%88/\" target=\"_blank\" rel=\"noreferrer noopener ugc\">問題解決のためのチェックリスト</a>』に記載されている『トラブルシューティングの基本』をご覧になり、ひととおりお試しください。</p>\n\n\n\n<p>ログインできない状態ですので、サーバーのファイルマネージャ もしくは FTP ソフトを利用してアクセスし、プラグインフォルダのリネーム等をお試しください。</p>\n\n\n\n<p>「サーバー名 FTP」 「サーバー名 ファイルマネージャー」 などの言葉で調べるとサーバーのマニュアルが出てくると思います。</p>\n\n\n\n<p>―</p>\n\n\n\n<p>※ このフォーラムは誰でも閲覧可能です。ログイン URL などは共有いただかぬようご注意ください。</p>\n\n\n<ul id=\"bbp-reply-revision-log-11691834\" class=\"bbp-reply-revision-log\">\n\n	<li id=\"bbp-reply-revision-log-11691834-item-11691835\" class=\"bbp-reply-revision-log-item\">\n		この返信は3日、 8時間前に<a href=\"https://ja.wordpress.org/support/users/setouchikotori/\" title=\"瀬戸内ことり (Setouchi Kotori) のプロフィールを表示\" class=\"bbp-author-link\"><span  class=\"bbp-author-name\">瀬戸内ことり (Setouchi Kotori)</span></a>が編集しました。\n	</li>\n\n</ul>\n\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"瀬戸内ことり (Setouchi Kotori)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:44:\"https://ja.wordpress.org/support/forums/feed\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";O:48:\"WpOrg\\Requests\\Utility\\CaseInsensitiveDictionary\":1:{s:7:\"\0*\0data\";a:10:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Sun, 04 May 2025 13:27:12 GMT\";s:12:\"content-